            if attempt == 4:
                logger.debug(
                    "problem removing data dir %s\nConsider checking whether it's there and remove it by hand\nerror: %s",
                    self.config.user_data_dir,
                    e,
                )
            await asyncio.sleep(0.15)
            continue

def __del__(self) -> None:
    pass
